const orders = $input.all().map(item => item.json);

const customers = {};

for (const order of orders) {
  const customerId = order.customer_id;
  const orderDate = new Date(order.order_date);

  if (!customers[customerId]) {
    customers[customerId] = {
      customer_id: customerId,
      customer_name: order.customer_name,
      first_purchase_date: order.order_date
    };
  }

  // پیدا کردن اولین خرید
  if (
    orderDate <
    new Date(customers[customerId].first_purchase_date)
  ) {
    customers[customerId].first_purchase_date = order.order_date;
  }
}

const result = Object.values(customers).map(customer => {

  const firstPurchase = new Date(
    customer.first_purchase_date
  );

  // تبدیل اولین خرید به اولین روز ماه
  const cohortMonth =
    `${firstPurchase.getUTCFullYear()}-${String(
      firstPurchase.getUTCMonth() + 1
    ).padStart(2, '0')}-01`;

  return {
    json: {
      customer_id: customer.customer_id,
      customer_name: customer.customer_name,
      first_purchase_date:
        customer.first_purchase_date,
      cohort_month: cohortMonth
    }
  };
});

return result;

const orders = $('Get Cohort').all();
const customers = $input.all();

// ساخت Map برای Cohort هر مشتری
const cohortMap = {};

for (const item of customers) {
  const customer = item.json;

  cohortMap[customer.customer_id] = {
    cohort_month: customer.cohort_month
  };
}

const result = orders.map(item => {
  const order = item.json;
  const cohort = cohortMap[order.customer_id];

  if (!cohort) {
    return null;
  }

  const orderDate = new Date(order.order_date);

  const orderMonth =
    `${orderDate.getUTCFullYear()}-${String(
      orderDate.getUTCMonth() + 1
    ).padStart(2, '0')}-01`;

  return {
    json: {
      order_id: order.order_id,
      customer_id: order.customer_id,
      customer_name: order.customer_name,
      order_date: order.order_date,
      order_month: orderMonth,
      cohort_month: cohort.cohort_month,
      amount: Number(order.amount) || 0
    }
  };
}).filter(item => item !== null);

return result;

const orders = $input.all();

const result = orders.map(item => {
  const o = item.json;

  const cohortDate = new Date(o.cohort_month);
  const orderDate = new Date(o.order_month);

  const monthNumber =
    (orderDate.getUTCFullYear() - cohortDate.getUTCFullYear()) * 12 +
    (orderDate.getUTCMonth() - cohortDate.getUTCMonth());

  return {
    json: {
      ...o,
      month_number: monthNumber
    }
  };
});

return result;

const orders = $input.all();

// برای هر cohort و هر month_number
// مشتری‌های یکتا را نگه می‌داریم
const groups = {};

for (const item of orders) {
  const o = item.json;

  const key = `${o.cohort_month}_${o.month_number}`;

  if (!groups[key]) {
    groups[key] = {
      cohort_month: o.cohort_month,
      month_number: o.month_number,
      customers: new Set()
    };
  }

  groups[key].customers.add(o.customer_id);
}

const result = Object.values(groups).map(group => {
  return {
    json: {
      cohort_month: group.cohort_month,
      month_number: group.month_number,
      customer_count: group.customers.size
    }
  };
});

return result;

const data = $input.all();

// پیدا کردن تعداد مشتری‌های ماه 0 هر Cohort
const cohortSizes = {};

for (const item of data) {
  const row = item.json;

  if (row.month_number === 0) {
    cohortSizes[row.cohort_month] = row.customer_count;
  }
}

// محاسبه Retention Rate
const result = data.map(item => {
  const row = item.json;

  const cohortSize = cohortSizes[row.cohort_month];

  const retentionRate =
    (row.customer_count / cohortSize) * 100;

  return {
    json: {
      cohort_month: row.cohort_month,
      month_number: row.month_number,
      customer_count: row.customer_count,
      retention_rate: Number(retentionRate.toFixed(2))
    }
  };
});

return result;
